SELECT DISTINCT client_id, meeting_outcome, meeting_type, billable_yn, purpose_of_meeting, other_details FROM Meetings INNER JOIN Clients ON meetings.client_id = clients.client_id;
SELECT DISTINCT staff_id, staff_details FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.client_id WHERE Meetings.meeting_type = 'S' OR Meetings.purpose_of_meeting = 'S' OR Meetings.other_details LIKE '%s' AND Staff.staff_details LIKE '%s'
SELECT Staff.staff_id, Staff.staff_details FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.client_id WHERE Meetings.meeting_type = 'S' AND Meetings.billable_yn = 'Y' AND Meetings.purpose_of_meeting = 'Meeting' AND Meetings.start_date_time IS NOT NULL;
SELECT DISTINCT client_id, meetings.client_id FROM Clients.client_id JOIN Meetings.meeting_id ON Meetings.client_id = Clients.client_id JOIN Staff.staff_id ON Staff.staff_id = Meetings.staff_id JOIN Staff_in_Meetings.staff_id ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings.meeting_id ON Staff_in_Meetings.meeting_id = Meetings.meeting_id JOIN Clients.client_id ON Meetings.client_id = Clients.client_id
SELECT DISTINCT client_id, meetings.client_id FROM Clients.client_id INNER JOIN Meetings ON Meetings.client_id = Clients.client_id WHERE Meetings.attended = TRUE AND Invoices.invoice_id = Payments.payment_id
SELECT M.start_date_time, M.end_date_time, C.client_details, S.staff_details FROM Clients C JOIN Meetings M ON C.agency_id = M.client_id JOIN Staff S ON M.staff_id = S.staff_id FROM Clients C
SELECT m.start_date_time, m.end_date_time, s.staff_id, c.client_id, s.staff_details, c.client_details FROM Clients c JOIN Agencies a ON c.agency_id = a.agency_id JOIN Staff s ON s.staff_id = s.staff_id JOIN Meetings m ON m.client_id = c.client_id JOIN Staff s ON s.staff_id = s.staff_id JOIN Clients c ON c.client_id = s.staff_details JOIN Staff s ON s.staff_id = s.staff_details JOIN Clients c ON c.client_id = c.client_details
